#include <stdint.h>
#include <stdio.h>
#include <string.h>

int is_little_endian(void) {
    uint16_t x = 1;
    unsigned char b;
    memcpy(&b, &x, 1);           /* first byte in memory */
    return b == 1;               /* 1 on LE, 0 on BE */
}

/* host-independent serialization of a 32-bit value, big-endian on the wire */
void put_be32(uint8_t *p, uint32_t v) {
    p[0] = (uint8_t)(v >> 24);
    p[1] = (uint8_t)(v >> 16);
    p[2] = (uint8_t)(v >> 8);
    p[3] = (uint8_t)v;
}

uint32_t get_be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8)  |  (uint32_t)p[3];
}

int main(void) {
    uint32_t v = 0x01234567u;
    unsigned char *p = (unsigned char *)&v;
    for (int i = 0; i < 4; i++) printf("%02x ", p[i]);   /* 67 45 23 01 on LE */
    printf("\n%s\n", is_little_endian() ? "little" : "big");
    return 0;
}

